DO $$
DECLARE gl_exists BOOLEAN;
BEGIN
    SELECT EXISTS(SELECT 1 FROM acc_gl_account WHERE gl_code = '1690952007') INTO gl_exists;
    IF NOT gl_exists THEN
        INSERT INTO acc_gl_account
            (id, gl_code, name, classification_enum, account_usage, manual_journal_entries_allowed, disabled, parent_id)
        VALUES
            (1690952007, '1690952007', 'CxC Comisión FNG', 1, 1, true, false, NULL);
    END IF;
END
$$;

DO $$ DECLARE max_id BIGINT; duplicate_charge RECORD; BEGIN -- Get the maximum ID from m_charge SELECT COALESCE(MAX(id), 0) INTO max_id FROM m_charge;
-- Find charges with duplicate IDs FOR duplicate_charge IN SELECT id, name FROM m_charge WHERE id IN ( SELECT id FROM m_charge GROUP BY id HAVING COUNT(*) > 1 ) LOOP -- Update the charge ID to max_id + 1 max_id := max_id + 1;
-- Update the charge ID UPDATE m_charge SET id = max_id WHERE id = duplicate_charge.id AND name = duplicate_charge.name;
-- Update any references in m_loan_charge UPDATE m_loan_charge SET charge_id = max_id WHERE charge_id = duplicate_charge.id; END LOOP; END $$;
